select (select count(*) from auth.users where id in ('ee350000-0000-4000-8000-000000000001','ee350000-0000-4000-8000-000000000009')) users,(select count(*) from public.companies where id='ee350000-0000-4000-8000-000000000002') companies,(select count(*) from private.advertising_publications where company_id='ee350000-0000-4000-8000-000000000002') publications,(select count(*) from private.advertising_publication_identities where company_id='ee350000-0000-4000-8000-000000000002') identities,(select count(*) from private.advertising_jobs where company_id='ee350000-0000-4000-8000-000000000002') jobs,(select count(*) from storage.objects where name like 'ee350000-0000-4000-8000-000000000002/%') storage_objects,(select count(*) from private.advertising_dispatchers where id='ee350000_fixture') dispatchers;
